<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { mentorAPI } from '../../api/mentor'
import type { Application, Organization, Project, ProjectUsage } from '../../api/types'
import { APIError } from '../../api/client'
import StatusBadge from '../../components/StatusBadge.vue'
import AppDialog from '../../components/AppDialog.vue'
import LoadingRegion from '../../components/LoadingRegion.vue'
import CreditDonut, { type CreditSegment } from '../../components/CreditDonut.vue'
import { useLoadState } from '../../composables/useLoadState'
import { useToast } from '../../composables/useToast'

const orgs=ref<Organization[]>([]),groups=ref<Array<{org:Organization;projects:Project[]}>>([]),applications=ref<Application[]>([]),activeProject=ref<Project|null>(null),projectUsage=ref<ProjectUsage|null>(null),quotaKey=ref<{id:string;name:string;quota:string}|null>(null),revokeKey=ref<{id:string;name:string}|null>(null),quota=ref(''),reason=ref(''),month=ref(new Date().toISOString().slice(0,7)),error=ref(''),toast=useToast(),loadState=useLoadState(),usageLoadState=useLoadState()
async function load(){await loadState.run(async()=>{try{orgs.value=await mentorAPI.organizations();groups.value=await Promise.all(orgs.value.map(async org=>({org,projects:await mentorAPI.projects(org.id)})));applications.value=await mentorAPI.applications();error.value=''}catch(e){error.value=msg(e)}})}
async function apply(project:Project){try{await mentorAPI.apply(project.id);toast.success('项目申请已提交');await load()}catch(e){error.value=msg(e)}}
async function showUsage(project:Project){activeProject.value=project;await usageLoadState.run(async()=>{try{projectUsage.value=await mentorAPI.usage(project.id,month.value);error.value=''}catch(e){error.value=msg(e)}})}
async function adjustQuota(){if(!quotaKey.value||!reason.value.trim())return;try{await mentorAPI.updateQuota(quotaKey.value.id,quota.value,reason.value);toast.success('Key 月额度已调整');quotaKey.value=null;reason.value='';await showUsage(activeProject.value!)}catch(e){error.value=msg(e)}}
async function revoke(){if(!revokeKey.value||!reason.value.trim())return;try{await mentorAPI.revoke(revokeKey.value.id,reason.value);toast.success('密钥已撤销并立即失效');revokeKey.value=null;reason.value='';await showUsage(activeProject.value!)}catch(e){error.value=msg(e)}}
function percent(used:string,quotaValue:string){return Number(quotaValue)===0?null:Number(used)/Number(quotaValue)*100}
function percentLabel(used:string,quotaValue:string){const value=percent(used,quotaValue);return value===null?'N/A':`${value.toFixed(1)}%`}
function memberQuota(member:ProjectUsage['members'][number]){return member.keys.reduce((sum,key)=>sum+Number(key.allocation),0).toFixed(3)}
function keyTrackWidth(member:ProjectUsage['members'][number],quotaValue:string){const maximum=Math.max(...member.keys.map(key=>Number(key.quota)),0);if(maximum===0)return 100;return Math.max(12,Number(quotaValue)/maximum*100)}
function allocationSegments(usage:ProjectUsage):CreditSegment[]{return[...usage.members.map(member=>({name:member.user_name,value:member.keys.reduce((sum,key)=>sum+Number(key.allocation),0)})).filter(item=>item.value>0),{name:'可分配额度',value:Number(usage.available),color:'#dfe3ec'}]}
function spendSegments(usage:ProjectUsage):CreditSegment[]{return[...usage.members.map(member=>({name:member.user_name,value:Number(member.credits)})).filter(item=>item.value>0),{name:'未消耗额度',value:Math.max(0,Number(usage.quota)-Number(usage.charged)),color:'#dfe3ec'}]}
function msg(e:unknown){return e instanceof APIError?e.message:'请求失败'}
onMounted(load)
</script>

<template><section class="page"><div class="page-heading"><div><p class="eyebrow">MENTOR</p><h1>项目管理</h1></div><button class="button secondary" @click="load">刷新</button></div><p v-if="error" class="error banner">{{error}}</p><LoadingRegion :initial-loading="loadState.initialLoading.value" :refreshing="loadState.refreshing.value" variant="split" label="正在加载项目和申请"><section v-for="group in groups" :key="group.org.id" class="panel" style="margin-bottom:20px"><h2>{{group.org.name}}</h2><div class="grid two"><article v-for="project in group.projects" :key="project.id" class="panel"><div class="row"><strong>{{project.name}}</strong><StatusBadge :status="project.status"/></div><p class="muted">{{project.description||'暂无说明'}} · 月额度 {{project.monthly_credit_quota}}</p><button v-if="project.is_responsible" class="button ghost" @click="showUsage(project)">查看额度与用量</button><button v-else class="button primary" :disabled="project.status!=='active'||project.application_status==='pending'" @click="apply(project)">{{project.application_status==='pending'?'审核中':'申请负责'}}</button></article></div></section><section class="panel"><h2>申请历史</h2><article v-for="item in applications" :key="item.id" class="list-row"><strong>{{item.project.name}}</strong><StatusBadge :status="item.status"/></article></section></LoadingRegion>

<AppDialog :open="Boolean(activeProject)" :title="`${activeProject?.name||''} · 额度与用量`" wide @update:open="activeProject=$event?activeProject:null"><div class="row"><p class="muted">数据按北京时间自然月统计</p><label>月份<input v-model="month" type="month" @change="activeProject&&showUsage(activeProject)"></label></div><LoadingRegion :initial-loading="usageLoadState.initialLoading.value" :refreshing="usageLoadState.refreshing.value" variant="list" label="正在加载项目用量"><template v-if="projectUsage"><div class="usage-summary usage-dialog-summary"><div class="usage-stat">项目月额度<strong>{{projectUsage.quota}}</strong></div><div class="usage-stat">已承诺额度<strong>{{projectUsage.allocated}}</strong></div><div class="usage-stat">可分配额度<strong>{{projectUsage.available}}</strong></div><div class="usage-stat">本月实际消耗<strong>{{projectUsage.charged}}</strong></div></div><div class="grid two"><section class="usage-chart-card"><h2>额度分配</h2><p class="muted">各成员名下所有 Key 的月额度之和</p><CreditDonut :segments="allocationSegments(projectUsage)" :total="Number(projectUsage.quota)" label="项目额度分配：成员已承诺额度与可分配额度"/></section><section class="usage-chart-card"><h2>实际开销</h2><p class="muted">按成员本月实际消耗的 credits 拆分</p><CreditDonut :segments="spendSegments(projectUsage)" :total="Number(projectUsage.quota)" label="项目实际开销：成员消耗与未消耗额度"/></section></div><table class="usage-table member-usage-table"><caption class="table-caption"><strong>成员 API Key 使用情况</strong> · 百分比表示“本月已用 credits / Key 月额度”，可超过 100%；0 额度显示 N/A。</caption><thead><tr><th scope="col">成员</th><th scope="col">成员分配额度</th><th scope="col">成员实际消耗</th><th scope="col">API Key 用量明细</th></tr></thead><tbody><tr v-for="member in projectUsage.members" :key="member.user_id"><th scope="row"><span class="member-name"><strong>{{member.user_name}}</strong><small class="muted">{{member.keys.length}} 个 Key</small></span></th><td class="numeric-cell">{{memberQuota(member)}} credits</td><td class="numeric-cell">{{member.credits}} credits</td><td><div class="key-usage-list"><article v-for="key in member.keys" :key="key.id" class="key-usage-item"><div class="key-usage-heading"><div><strong>{{key.name}}</strong><StatusBadge :status="key.status"/></div><small>{{key.used}} / {{key.quota}} credits</small></div><div class="key-progress-line"><div class="key-progress-track" :style="{width:`${keyTrackWidth(member,key.quota)}%`}" :title="`轨道长度表示 ${key.quota} credits Key 月额度`"><div class="quota-progress" role="progressbar" :aria-label="`${member.user_name} 的 ${key.name}：轨道长度表示 Key 月额度，填充表示本月已用 credits`" aria-valuemin="0" :aria-valuemax="Number(key.quota)" :aria-valuenow="Number(key.used)"><span :style="{width:`${Math.min(100,percent(key.used,key.quota)??0)}%`}"/></div></div><strong>{{percentLabel(key.used,key.quota)}}</strong></div><div class="actions"><button v-if="key.status==='active'||key.status==='approved'" class="button ghost" @click="quotaKey={id:key.id,name:key.name,quota:key.quota};quota=key.quota;reason=''">调整额度</button><button v-if="key.status==='active'" class="button danger" @click="revokeKey={id:key.id,name:key.name};reason=''">撤销</button></div></article><span v-if="!member.keys.length" class="muted">该成员本月无 Key</span></div></td></tr><tr v-if="!projectUsage.members.length"><td colspan="4" class="empty">该项目本月暂无成员 Key 数据</td></tr></tbody></table></template></LoadingRegion></AppDialog>

<AppDialog :open="Boolean(quotaKey)" :title="`调整 ${quotaKey?.name||''} 月额度`" @update:open="quotaKey=$event?quotaKey:null"><label>新月额度（credits）<input v-model="quota" inputmode="decimal"></label><label>调额原因<textarea v-model="reason" rows="3" required/></label><button class="button primary" :disabled="!reason.trim()" @click="adjustQuota">确认调额</button></AppDialog><AppDialog :open="Boolean(revokeKey)" :title="`撤销 ${revokeKey?.name||''}`" @update:open="revokeKey=$event?revokeKey:null"><label>撤销原因<textarea v-model="reason" rows="3" required/></label><button class="button danger" :disabled="!reason.trim()" @click="revoke">确认撤销</button></AppDialog></section></template>
